actions.script:
def _valid = ['insights','kpis','snapshot','activity','modules']
def _clean = ((context.order ?: '').toString().split(',') as List).findAll { _valid.contains(it) }.unique()
ec.user.setPreference('HOME_DASH_ORDER', _clean.join(','))
if (context.sizes != null) {
    def _sz = ((context.sizes ?: '').toString().split(',') as List)
            .collect { it.split(':') as List }
            .findAll { it.size()==2 && _valid.contains(it[0]) && it[1] in ['half','third'] }
            .collect { it[0]+':'+it[1] }
    ec.user.setPreference('HOME_DASH_SIZE', _sz.join(','))
}
ec.web.sendJsonResponse([saved:true, order:_clean.join(',')])

dateError = ''
def _parseDay = { value ->
    def text = (value ?: '').toString().trim()
    if (!text) return ''
    if (!(text ==~ /\d{4}-\d{2}-\d{2}/)) throw new IllegalArgumentException('Invalid date')
    return java.time.LocalDate.parse(text).toString()
}
dayStart = null; dayEndExcl = null
try {
    dashDate = _parseDay(dashDate); dashDateTo = _parseDay(dashDateTo)
    if (!dashDate && dashDateTo) dashDate = dashDateTo
} catch (Exception e) {
    dashDate = ''; dashDateTo = ''
    dateError = 'Choose valid dates in YYYY-MM-DD format. Showing all time.'
}
if (dashDate) {
    if (!dashDateTo) dashDateTo = dashDate
    if (dashDateTo < dashDate) { def _s = dashDate; dashDate = dashDateTo; dashDateTo = _s }
    dayStart = java.sql.Timestamp.valueOf(dashDate + " 00:00:00")
    def _ce = java.util.Calendar.getInstance(); _ce.setTime(java.sql.Timestamp.valueOf(dashDateTo + " 00:00:00")); _ce.add(java.util.Calendar.DAY_OF_MONTH, 1)
    dayEndExcl = new java.sql.Timestamp(_ce.getTimeInMillis())
}

def EC = org.moqui.entity.EntityCondition
def _n = ec.user.nowTimestamp
def _w1 = new java.sql.Timestamp(_n.time - 7L*86400000L)
homeDataErrors = []
def _read = { label, source ->
    try { return activeOrgId ? source() : [] }
    catch (Exception e) { homeDataErrors.add(label); ec.logger.warn('Home dashboard: '+label+' unavailable', e); return [] }
}
homeBd = { v -> v == null ? BigDecimal.ZERO : v as BigDecimal }
homeInvoiceTotal = { inv -> inv.invoiceTotal != null ? homeBd(inv.invoiceTotal) : homeBd(inv.totalTaxableAmount)+homeBd(inv.totalTaxAmount) }
homeUnpaid = { inv -> (inv.unpaidTotal != null ? homeBd(inv.unpaidTotal) : homeInvoiceTotal(inv)-homeBd(inv.appliedPaymentsTotal)).max(BigDecimal.ZERO) }
homeMoney = { v -> zinr.inr(ec.l10n.format(homeBd(v), '#,##0.##')) }
homeSales = _read('Sales', { ec.entity.find('mantle.account.invoice.Invoice').condition('fromPartyId',activeOrgId)
    .condition('invoiceTypeEnumId','InvoiceSales').condition('statusId','in',['InvoiceFinalized','InvoicePmtRecvd']).disableAuthz().list() })
homePurchases = _read('Vendor bills', { ec.entity.find('mantle.account.invoice.Invoice').condition('toPartyId',activeOrgId)
    .condition('invoiceTypeEnumId','InvoicePurchase').condition('statusId',EC.NOT_IN,['InvoiceInProcess','InvoiceCancelled','InvoicePmtSent','InvoicePmtRecvd','InvoiceWriteOff']).disableAuthz().list() })
homePos = _read('POS balances', { ec.entity.find('zenith.erp.pos.PosTransaction').condition('organizationPartyId',activeOrgId)
    .condition('statusId','PtCompleted').disableAuthz().list() })
homeInRange = { date -> date != null && (dayStart == null || (!date.before(dayStart) && date.before(dayEndExcl))) }
def _salesBetween = { a, b -> homeSales.findAll { it.invoiceDate != null && !it.invoiceDate.before(a) && it.invoiceDate.before(b) }.sum { homeInvoiceTotal(it) } ?: BigDecimal.ZERO }
def _finSales = homeSales.findAll { homeInRange(it.invoiceDate) }.sum { homeInvoiceTotal(it) } ?: BigDecimal.ZERO
def _trendEnd = dayEndExcl ?: _n
def _trendStart = dayStart ?: _w1
def _trendPrior = new java.sql.Timestamp(_trendStart.time - (_trendEnd.time-_trendStart.time))
def _sCur = _salesBetween(_trendStart, _trendEnd); def _sPrev = _salesBetween(_trendPrior, _trendStart)
def _salesTrend = _sPrev > 0 ? [dir:(_sCur>=_sPrev?'up':'down'), pct:(int)Math.round(Math.abs((_sCur-_sPrev).doubleValue()*100/_sPrev.doubleValue()))] : null
homePendingInvoices = homePurchases.findAll { homeUnpaid(it)>0 }
def _finPay = homePendingInvoices.sum { homeUnpaid(it) } ?: BigDecimal.ZERO
def _linked = homePos.collect { it.linkedInvoiceId }.findAll { it } as Set
homeCreditInvoices = homeSales.findAll { !_linked.contains(it.invoiceId) && homeUnpaid(it)>0 }
def _finRecv = (homePos.findAll { it.isCredit=='Y' }.sum { (homeBd(it.payableAmount)-homeBd(it.paidAmount)).max(BigDecimal.ZERO) } ?: BigDecimal.ZERO)
_finRecv += homeCreditInvoices.sum { homeUnpaid(it) } ?: BigDecimal.ZERO
def _cashPos = homePos.findAll { homeInRange(it.completedDate ?: it.entryDate) }
def _finCash = BigDecimal.ZERO
if (_cashPos) {
    def _payments = _read('Cash receipts', { ec.entity.find('zenith.erp.pos.PosPayment').condition('transactionId','in',_cashPos*.transactionId).condition('paymentMethod','Cash').disableAuthz().list() })
    _finCash = (_payments.sum { homeBd(it.amount) } ?: BigDecimal.ZERO) - (_cashPos.sum { homeBd(it.changeAmount) } ?: BigDecimal.ZERO)
}
def _cashEntries = _read('Cash entries', { ec.entity.find('zenith.erp.pos.PosCashEntry').condition('organizationPartyId',activeOrgId).disableAuthz().list() })
_cashEntries.findAll { homeInRange(it.entryDate) }.each {
    if (it.entryType=='CashIn') _finCash+=homeBd(it.amount)
    else if (it.entryType=='CashOut') _finCash-=homeBd(it.amount)
}
kpiCards = [
    [lab:'Total Sales', disp:homeMoney(_finSales), icon:'trending_up', tintBg:'#FEF3C7', tintFg:'#D97706', url:'/apps/zenith/sales/FindInvoice', trend:_salesTrend, extra:'No. of Invoices: '+homeSales.count { homeInRange(it.invoiceDate) }, source:['Sales']],
    [lab:'Total Payables', disp:homeMoney(_finPay), icon:'receipt_long', tintBg:'#FEE2E2', tintFg:'#DC2626', url:'/apps/zenith/Purchase/PurchaseInvoices', trend:null, extra:'Outstanding vendor balances', source:['Vendor bills']],
    [lab:'Total Receivable', disp:homeMoney(_finRecv), icon:'account_balance_wallet', tintBg:'#DBEAFE', tintFg:'#3B82F6', url:'/apps/zenith/pos/CreditBills', trend:null, extra:'POS credits and sales invoices', source:['Sales','POS balances']],
    [lab:'Cash in Hand', disp:homeMoney(_finCash), icon:'payments', tintBg:'#D1FAE5', tintFg:'#059669', url:'/apps/zenith/pos/CashEntry', trend:null, extra:'Net cash sales and cash entries', source:['POS balances','Cash receipts','Cash entries']]
]
kpiCards.each { it.available = activeOrgId && !it.source.any { source -> homeDataErrors.contains(source) } }

moduleList = [
    [id:'Z_POS', name:'POS Terminal', url:'/apps/zenith/pos/Terminal', bg:'bg-green-1'],
    [id:'Z_SALES', name:'Sales', url:'/apps/zenith/sales/SalesDashboard', bg:'bg-indigo-1'],
    [id:'Z_PURCHASE', name:'Purchase', url:'/apps/zenith/Purchase/RfqList', bg:'bg-teal-1'],
    [id:'Z_INVENTORY', name:'Inventory', url:'/apps/zenith/Inventory/FindProduct', bg:'bg-orange-1'],
    [id:'Z_ACCOUNTING', name:'Accounting', url:'/apps/zenith/Accounting/AcctgDashboard', bg:'bg-purple-1'],
    [id:'Z_TAX', name:'Tax', url:'/apps/zenith/tax/TaxDashboard', bg:'bg-teal-1'],
    [id:'Z_PRICING', name:'Pricing', url:'/apps/zenith/pricing/PricingDashboard', bg:'bg-amber-1'],
    [id:'Z_STORES', name:'Stores', url:'/apps/zenith/Stores/FindStore', bg:'bg-green-1'],
    [id:'Z_BARCODE', name:'Barcode', url:'/apps/zenith/barcode/BarcodeDashboard', bg:'bg-cyan-1'],
    [id:'Z_CONTACTS', name:'Contacts', url:'/apps/zenith/Contacts/FindContact', bg:'bg-blue-1'],
    [id:'Z_CRM', name:'CRM', url:'/apps/zenith/Crm/Leads', bg:'bg-pink-1'],
    [id:'Z_HR', name:'HR', url:'/apps/zenith/Hr/Employees', bg:'bg-amber-1'],
    [id:'Z_PAYROLL', name:'Payroll', url:'/apps/zenith/payroll/PayrollRuns', bg:'bg-green-1'],
    [id:'Z_ATTENDANCE', name:'Attendance', url:'/apps/zenith/attendance/MyAttendance', bg:'bg-blue-grey-1'],
    [id:'Z_TIMEOFF', name:'Time Off', url:'/apps/zenith/timeoff/MyLeaves', bg:'bg-cyan-1'],
    [id:'Z_RECRUITMENT', name:'Recruitment', url:'/apps/zenith/recruitment/Applications', bg:'bg-deep-orange-1'],
    [id:'Z_EXPENSES', name:'Expenses', url:'/apps/zenith/expenses/MyExpenses', bg:'bg-orange-1'],
    [id:'Z_MANUFACTURING', name:'Manufacturing', url:'/apps/zenith/manufacturing/WorkOrders', bg:'bg-indigo-1'],
    [id:'Z_QUALITY', name:'Quality', url:'/apps/zenith/quality/Inspections', bg:'bg-teal-1'],
    [id:'Z_MAINTENANCE', name:'Maintenance', url:'/apps/zenith/maintenance/MaintenanceDashboard', bg:'bg-amber-1'],
    [id:'Z_FLEET', name:'Fleet', url:'/apps/zenith/fleet/FleetDashboard', bg:'bg-blue-grey-1'],
    [id:'Z_HELPDESK', name:'Helpdesk', url:'/apps/zenith/helpdesk/Tickets', bg:'bg-pink-1'],
    [id:'Z_MARKETING', name:'Marketing', url:'/apps/zenith/marketing/Campaigns', bg:'bg-purple-1'],
    [id:'Z_ECOMMERCE', name:'eCommerce', url:'/apps/zenith/ecommerce/EcomOrders', bg:'bg-blue-1'],
    [id:'Z_EVENTS', name:'Events', url:'/apps/zenith/events/AllEvents', bg:'bg-green-1'],
    [id:'Z_SUBSCRIPTIONS', name:'Subscriptions', url:'/apps/zenith/subscriptions/AllSubscriptions', bg:'bg-orange-1'],
    [id:'Z_DOCUMENTS', name:'Documents', url:'/apps/zenith/documents/DocumentList', bg:'bg-blue-grey-1'],
    [id:'Z_APPROVALS', name:'Approvals', url:'/apps/zenith/approvals/MyApprovals', bg:'bg-cyan-1'],
    [id:'Z_INTEGRATIONS', name:'Integrations', url:'/apps/zenith/integrations/PortalConfig', bg:'bg-deep-orange-1'],
    [id:'Z_WEBSITE', name:'Website', url:'/apps/zenith/website/Sites', bg:'bg-indigo-1'],
    [id:'Z_STUDIO', name:'Studio', url:'/apps/zenith/studio/CustomFields', bg:'bg-purple-1'],
    [id:'Z_PLM', name:'PLM', url:'/apps/zenith/plm/EngineeringChangeOrders', bg:'bg-teal-1'],
    [id:'Z_FIELDSERVICE', name:'Field Service', url:'/apps/zenith/fieldservice/Tasks', bg:'bg-amber-1'],
    [id:'Z_DISCUSS', name:'Discuss', url:'/apps/zenith/discuss/Channels', bg:'bg-pink-1'],
    [id:'Z_SIGN', name:'E-Sign', url:'/apps/zenith/sign', bg:'bg-blue-1'],
    [id:'Z_PROJECT', name:'Projects', url:'/apps/zenith/project', bg:'bg-green-1'],
    [id:'Z_TIMESHEETS', name:'Timesheets', url:'/apps/zenith/timesheets', bg:'bg-orange-1'],
    [id:'Z_SETTINGS', name:'Settings', url:'/apps/zenith/Settings/CompanySetup', bg:'bg-blue-grey-1']
]

// Filter modules by RBAC
// Plan-aware module tiles: SaaS tenants see only modules included in their plan AND granted by
// their ROLES (ZE-ROLES-001 — a plan-only filter let a Cashier+HR-Manager see every plan module,
// an escalation appearance; admins keep the full plan list via isAdmin). Non-tenant / all-access
// fall back to pure RBAC.
if (isSaasTenant && !saasHasAllAccess && saasAllowedModules != null) {
    filteredModules = moduleList.findAll { mod -> saasAllowedModules.contains(mod.id.replaceFirst('Z_','').toLowerCase()) && (isAdmin || accessSet.contains(mod.id)) }
} else {
    filteredModules = moduleList.findAll { mod -> isAdmin || accessSet.contains(mod.id) }
}
// ZE-POS-0201: a POS-only cashier is till-first but may step into POS + Inventory only, so keep
// their Dashboard to those two tiles — every other module bounces back to the terminal anyway.
def _zc = myGroupIds.findAll { it?.startsWith('ZENITH_') && it != 'ZENITH_ALL' }
if (!isAdmin && _zc.size() == 1 && _zc.contains('ZENITH_CASHIER')) {
    filteredModules = filteredModules.findAll { it.id == 'Z_POS' || it.id == 'Z_INVENTORY' }
} else {
    // ZE-DASH: Dashboard + (tenant only) My Subscription aren't plan modules but should still be reachable
    // from the "All Modules" grid; append them after the plan/role filter (the till-first cashier is excluded).
    filteredModules = filteredModules + [[id:'Z_DASHBOARD', name:'Dashboard', url:'/apps/zenith', bg:'bg-indigo-1']]
    if (isSaasTenant) filteredModules = filteredModules + [[id:'Z_MYSUB', name:'My Subscription', url:'/vapps/zenith/my-subscription', bg:'bg-green-1']]
}

// Quick Actions — plan-aware (SaaS tenants: by plan; admins / non-tenant: by RBAC)
boolean qaPlanMode = (isSaasTenant && !saasHasAllAccess && saasAllowedModules != null)
def qaPlanHas = { k -> isSaasTenant && (saasHasAllAccess || (saasAllowedModules != null && saasAllowedModules.contains(k))) }
// ZE-ROLES-001: Quick Actions are also plan AND role scoped for tenants (was plan-only).
def qaCan = { modId, key -> qaPlanMode ? (qaPlanHas(key) && (isAdmin || accessSet.contains(modId))) : (isAdmin || accessSet.contains(modId)) }
qaGroups = []
def qaPos = []
if (qaCan('Z_POS','pos')) { qaPos << [t:'Open POS Terminal', u:'/apps/zenith/pos/Terminal']; qaPos << [t:'POS Sessions', u:'/apps/zenith/pos/PosSessions'] }
if (qaPos) qaGroups << [title:'Point of Sale', color:'text-green-8', links:qaPos]
def qaSales = []
if (qaCan('Z_SALES','sales')) { qaSales << [t:'New Sales Order', u:'/apps/zenith/sales/CreateOrder']; qaSales << [t:'Create Invoice', u:'/apps/zenith/sales/CreateInvoice']; qaSales << [t:'New Quotation', u:'/apps/zenith/sales/CreateQuotation'] }
if (qaCan('Z_CRM','crm')) { qaSales << [t:'Manage Leads', u:'/apps/zenith/Crm/Leads']; qaSales << [t:'Sales Pipeline', u:'/apps/zenith/Crm/Pipeline'] }
if (qaSales) qaGroups << [title:'Sales & CRM', color:'text-indigo-8', links:qaSales]
def qaInv = []
if (qaCan('Z_PURCHASE','purchase')) { qaInv << [t:'New Purchase Order', u:'/apps/zenith/Purchase/CreatePurchaseOrder']; qaInv << [t:'Log Vendor Bill', u:'/apps/zenith/Purchase/CreatePurchaseInvoice'] }
if (qaCan('Z_INVENTORY','inventory')) { qaInv << [t:'Product Catalog', u:'/apps/zenith/Inventory/FindProduct']; qaInv << [t:'Stock Levels', u:'/apps/zenith/Inventory/StockLevels']; qaInv << [t:'Stock Transfers', u:'/apps/zenith/Inventory/StockTransfers'] }
if (qaInv) qaGroups << [title:(qaCan('Z_PURCHASE','purchase') ? 'Purchase & Inventory' : 'Inventory'), color:'text-teal-8', links:qaInv]
def qaAcct = []
if (qaCan('Z_ACCOUNTING','accounting')) { qaAcct << [t:'Journal Entry', u:'/apps/zenith/Accounting/ManualJournalEntry']; qaAcct << [t:'Chart of Accounts', u:'/apps/zenith/Accounting/ChartOfAccounts']; qaAcct << [t:'Bank Reconciliation', u:'/apps/zenith/Accounting/AutoBrs']; qaAcct << [t:'Profit & Loss', u:'/apps/zenith/Accounting/ProfitAndLoss'] }
if (qaCan('Z_EXPENSES','expenses')) { qaAcct << [t:'Expense Reports', u:'/apps/zenith/expenses/MyExpenses'] }
if (qaAcct) qaGroups << [title:'Accounting & Finance', color:'text-green-8', links:qaAcct]
def qaPeople = []
if (qaCan('Z_CONTACTS','contacts')) { qaPeople << [t:'Add Contact', u:'/apps/zenith/Contacts/FindContact?newContact=1']; qaPeople << [t:'Contact Directory', u:'/apps/zenith/Contacts/FindContact']; qaPeople << [t:'Vendor Directory', u:'/apps/zenith/Contacts/Vendors'] }
if (qaCan('Z_HR','hr')) { qaPeople << [t:'Employees', u:'/apps/zenith/Hr/Employees'] }
if (qaCan('Z_RECRUITMENT','recruitment')) { qaPeople << [t:'Recruitment', u:'/apps/zenith/recruitment/Applications'] }
if (qaPeople) qaGroups << [title:'Contacts & People', color:'text-deep-purple-8', links:qaPeople]

// ZE-DASH restructure: compact 6-tile Quick Actions (icon grid) shown beside the chart. Same
// plan/role gating as qaGroups (qaCan) so a tile only appears if the user can actually use it.
homeTiles = []
if (qaCan('Z_POS','pos'))               homeTiles << [label:'New Sale',     icon:'add',           url:'/apps/zenith/pos/Terminal']
if (qaCan('Z_PURCHASE','purchase'))     homeTiles << [label:'New Purchase', icon:'shopping_cart', url:'/apps/zenith/Purchase/CreatePurchaseOrder']
if (qaCan('Z_SALES','sales'))           homeTiles << [label:'New Invoice',  icon:'description',   url:'/apps/zenith/sales/CreateInvoice']
if (qaCan('Z_PURCHASE','purchase'))     homeTiles << [label:'New Bill',     icon:'request_quote', url:'/apps/zenith/Purchase/CreatePurchaseInvoice']
if (qaCan('Z_ACCOUNTING','accounting')) homeTiles << [label:'Bank Recon',   icon:'sync_alt',      url:'/apps/zenith/Accounting/AutoBrs']
if (qaCan('Z_CONTACTS','contacts'))     homeTiles << [label:'Add Contact',  icon:'person_add',    url:'/apps/zenith/Contacts/FindContact?newContact=1']

import org.moqui.entity.EntityCondition
def ef = ec.entity
def _sdf = new java.text.SimpleDateFormat("yyyy-MM-dd")
def _now = ec.user.nowTimestamp
def _todayStr = _sdf.format(_now)
def _cw = java.util.Calendar.getInstance(); _cw.setTime(_now); _cw.set(java.util.Calendar.DAY_OF_WEEK, _cw.getFirstDayOfWeek()); def _weekStartStr = _sdf.format(_cw.getTime())
def _cm = java.util.Calendar.getInstance(); _cm.setTime(_now); _cm.set(java.util.Calendar.DAY_OF_MONTH,1); def _monthStartStr = _sdf.format(_cm.getTime())
def _c30 = java.util.Calendar.getInstance(); _c30.setTime(_now); _c30.add(java.util.Calendar.DAY_OF_MONTH,-29); def _last30Str = _sdf.format(_c30.getTime())
urlAll = "?"; urlToday = "?dateMode=today&dashDate="+_todayStr+"&dashDateTo="+_todayStr
urlWeek = "?dateMode=week&dashDate="+_weekStartStr+"&dashDateTo="+_todayStr
urlMonth = "?dateMode=month&dashDate="+_monthStartStr+"&dashDateTo="+_todayStr
url30 = "?dashDate="+_last30Str+"&dashDateTo="+_todayStr
presetActive = 'all'
if (dashDate) {
    presetActive = 'custom'
    if (dashDateTo == _todayStr) {
        if (dashDate == _todayStr) presetActive='today'
        else if (dashDate == _weekStartStr) presetActive='week'
        else if (dashDate == _monthStartStr) presetActive='month'
        else if (dashDate == _last30Str) presetActive='last30'
    }
}
// ZE-DATEWISE: This Year preset + "Date-wise" custom-range tab (self-contained; var-name-agnostic)
def _dwSdf = new java.text.SimpleDateFormat("yyyy-MM-dd"); def _dwNow = ec.user.nowTimestamp; def _dwToday = _dwSdf.format(_dwNow)
def _dwYc = java.util.Calendar.getInstance(); _dwYc.setTime(_dwNow); _dwYc.set(java.util.Calendar.MONTH,0); _dwYc.set(java.util.Calendar.DAY_OF_MONTH,1); def _dwYearStart = _dwSdf.format(_dwYc.getTime())
urlYear = "?dateMode=year&dashDate="+_dwYearStart+"&dashDateTo="+_dwToday
if (dashDate && dashDateTo == _dwToday && dashDate == _dwYearStart) presetActive = 'year'
// Keep the chosen tab when Today, This Week or This Month share the same bounds.
def _presetStarts = [today:_todayStr, week:_weekStartStr, month:_monthStartStr, year:_dwYearStart]
if (_presetStarts.containsKey(dateMode) && dashDate == _presetStarts[dateMode] && dashDateTo == _todayStr) presetActive = dateMode
showCustom = (((dateMode ?: '') == 'custom') || (presetActive == 'custom'))
urlCustom = dashDate ? ("?dateMode=custom&dashDate="+dashDate+"&dashDateTo="+dashDateTo) : "?dateMode=custom"
acRangeLabel = dashDate ? (dashDate == dashDateTo ? dashDate : (dashDate + ' to ' + dashDateTo)) : 'All time'
def _controlDay = java.time.format.DateTimeFormatter.ofPattern('dd MMM', java.util.Locale.ENGLISH)
def _controlEnd = java.time.format.DateTimeFormatter.ofPattern('dd MMM yyyy', java.util.Locale.ENGLISH)
homeRangeLabel = 'All time'
homeNextRangeUrl = ''
if (dashDate) {
    def _from = java.time.LocalDate.parse(dashDate), _to = java.time.LocalDate.parse(dashDateTo)
    homeRangeLabel = _from.format(_from.year == _to.year ? _controlDay : _controlEnd) + ' – ' + _to.format(_controlEnd)
    def _rangeDays = java.time.temporal.ChronoUnit.DAYS.between(_from, _to) + 1
    homeNextRangeUrl = '?dateMode=custom&dashDate=' + _from.plusDays(_rangeDays) + '&dashDateTo=' + _to.plusDays(_rangeDays)
}

// ZE-DASH SALES ANALYST (2026-08): two client-switchable views — Weekly (sales ₹ per day, current week)
// and Today Hourly (sales ₹ per hour today). Metric = finalised InvoiceSales invoiceTotal (SAME basis as
// the Total Sales KPI above), org-scoped. Empty -> flat zero line + a "No sales" subtitle (never blank).
def _saSum = { a, b -> homeSales.findAll { it.invoiceDate != null && !it.invoiceDate.before(a) && it.invoiceDate.before(b) }.sum { homeInvoiceTotal(it) } ?: BigDecimal.ZERO }
def _wkCal = java.util.Calendar.getInstance(); _wkCal.setTime(_now)
_wkCal.set(java.util.Calendar.DAY_OF_WEEK, _wkCal.firstDayOfWeek)
_wkCal.set(java.util.Calendar.HOUR_OF_DAY,0); _wkCal.set(java.util.Calendar.MINUTE,0); _wkCal.set(java.util.Calendar.SECOND,0); _wkCal.set(java.util.Calendar.MILLISECOND,0)
def _chartStart = dayStart ?: new java.sql.Timestamp(_wkCal.timeInMillis)
def _chartEnd = dayEndExcl
if (_chartEnd == null) { def c=(java.util.Calendar)_wkCal.clone(); c.add(java.util.Calendar.DAY_OF_MONTH,7); _chartEnd=new java.sql.Timestamp(c.timeInMillis) }
boolean _monthly = (_chartEnd.time-_chartStart.time)>62L*86400000L
boolean _yearly = (_chartEnd.time-_chartStart.time)>400L*31*86400000L
def _bucketField = _yearly ? java.util.Calendar.YEAR : (_monthly ? java.util.Calendar.MONTH : java.util.Calendar.DAY_OF_MONTH)
def _bucketStep = _yearly ? Math.max(1,(int)Math.ceil((_chartEnd.toLocalDateTime().year-_chartStart.toLocalDateTime().year+1)/399.0)) : 1
def _bucket = java.util.Calendar.getInstance(); _bucket.setTime(_chartStart)
if (_monthly) _bucket.set(java.util.Calendar.DAY_OF_MONTH,1)
if (_yearly) _bucket.set(java.util.Calendar.MONTH,0)
def _labelFmt = new java.text.SimpleDateFormat(_yearly ? 'yyyy' : (_monthly ? 'MMM yy' : (dayStart ? 'dd MMM' : 'EEE')))
def _labels=[]; def _values=[]; def _total=BigDecimal.ZERO
while (_bucket.timeInMillis < _chartEnd.time && _labels.size()<400) {
    def next=(java.util.Calendar)_bucket.clone(); next.add(_bucketField,_bucketStep)
    def a=new java.sql.Timestamp(Math.max(_bucket.timeInMillis,_chartStart.time))
    def b=new java.sql.Timestamp(Math.min(next.timeInMillis,_chartEnd.time))
    def v=_saSum(a,b); _labels.add(_labelFmt.format(_bucket.time)); _values.add(v); _total+=v; _bucket=next
}
baWeekLabelsJson = groovy.json.JsonOutput.toJson(_labels); baWeekDataJson = groovy.json.JsonOutput.toJson(_values)
baWeekTotal = _total; baWeekTotalFmt = homeMoney(_total)
baWeekLabel = dayStart ? acRangeLabel : 'This week'
def _today = java.sql.Timestamp.valueOf(_todayStr+' 00:00:00')
def _tomorrowCal=java.util.Calendar.getInstance(); _tomorrowCal.setTime(_today); _tomorrowCal.add(java.util.Calendar.DAY_OF_MONTH,1)
def _tomorrow=new java.sql.Timestamp(_tomorrowCal.timeInMillis)
def _hours=(0..<24).collect { BigDecimal.ZERO }
homeSales.findAll { it.invoiceDate != null && !it.invoiceDate.before(_today) && it.invoiceDate.before(_tomorrow) }.each {
    def c=java.util.Calendar.getInstance(); c.setTime(it.invoiceDate); _hours[c.get(java.util.Calendar.HOUR_OF_DAY)]+=homeInvoiceTotal(it)
}
baHourLabelsJson=groovy.json.JsonOutput.toJson((0..<24).collect { h -> (h%12==0?12:h%12).toString()+(h<12?'AM':'PM') })
baHourDataJson=groovy.json.JsonOutput.toJson(_hours); baHourTotal=_hours.sum(); baHourTotalFmt=homeMoney(baHourTotal)

// ZE-DASH layout: switchable widgets (+ cashier role default) + saved drag order
def _roleHidden = ''
try {
    if (!isAdmin) {
        def _zrp = (myGroupIds ?: []).findAll { it?.startsWith("ZENITH_") && it != "ZENITH_ALL" }
        if (_zrp.size() == 1 && _zrp.contains("ZENITH_CASHIER")) _roleHidden = 'activity'
    }
} catch (Exception e) {}
def _pref = ec.user.getPreference('HOME_DASH_HIDDEN')
def _hiddenSet = ((_pref != null) ? _pref : _roleHidden).split(',').findAll { it }.toSet()
showInsights = !_hiddenSet.contains('insights'); showSnapshot = !_hiddenSet.contains('snapshot')
showKpis = !_hiddenSet.contains('kpis'); showActivity = !_hiddenSet.contains('activity')
showModules = !_hiddenSet.contains('modules')
w_insights = showInsights ? 'Y' : ''; w_snapshot = showSnapshot ? 'Y' : ''
w_kpis = showKpis ? 'Y' : ''; w_activity = showActivity ? 'Y' : ''
w_modules = showModules ? 'Y' : ''
dashOrderCsv = (ec.user.getPreference('HOME_DASH_ORDER') ?: '')
dashSizeCsv = (ec.user.getPreference('HOME_DASH_SIZE') ?: '')
urlSettings = dashDate ? ("?dashDate="+dashDate+"&dashDateTo="+dashDateTo+"&showSettings=1" + (_presetStarts.containsKey(dateMode) ? "&dateMode="+dateMode : '')) : "?showSettings=1"

def _EC = org.moqui.entity.EntityCondition
def _bd = { v -> (v ?: 0) as BigDecimal }
def _org2 = activeOrgId
def _now2 = ec.user.nowTimestamp
def _fmt = { v -> '₹' + homeMoney(v) }
def _finSale = ['InvoiceFinalized','InvoicePmtRecvd']

// date windows: the selected range if set, else last 30 days; prior = equal-length preceding window
def _wStart; def _wEnd
if (dayStart) { _wStart = dayStart; _wEnd = dayEndExcl }
else {
    def _ce = java.util.Calendar.getInstance(); _ce.setTime(_now2); _ce.add(java.util.Calendar.DAY_OF_MONTH,1)
    _ce.set(java.util.Calendar.HOUR_OF_DAY,0); _ce.set(java.util.Calendar.MINUTE,0); _ce.set(java.util.Calendar.SECOND,0); _ce.set(java.util.Calendar.MILLISECOND,0)
    _wEnd = new java.sql.Timestamp(_ce.getTimeInMillis())
    def _cs = java.util.Calendar.getInstance(); _cs.setTime(_now2); _cs.add(java.util.Calendar.DAY_OF_MONTH,-29)
    _cs.set(java.util.Calendar.HOUR_OF_DAY,0); _cs.set(java.util.Calendar.MINUTE,0); _cs.set(java.util.Calendar.SECOND,0); _cs.set(java.util.Calendar.MILLISECOND,0)
    _wStart = new java.sql.Timestamp(_cs.getTimeInMillis())
}
def _wMs = _wEnd.getTime() - _wStart.getTime()
def _pStart = new java.sql.Timestamp(_wStart.getTime() - _wMs)

// finalised sales total in [a,b)
def _salesIn = { a,b -> homeSales.findAll { it.invoiceDate != null && !it.invoiceDate.before(a) && it.invoiceDate.before(b) }.sum { homeInvoiceTotal(it) } ?: BigDecimal.ZERO }
def _salesCur = _salesIn(_wStart, _wEnd)
def _salesPrior = _salesIn(_pStart, _wStart)
def _salesGrowth = _salesPrior > 0 ? ((_salesCur.doubleValue()-_salesPrior.doubleValue())*100.0/_salesPrior.doubleValue()) : (_salesCur>0?100.0:0.0)

// receivables + overdue from POS credit bills (honest source), + any real credit invoices past due date
def _recv = BigDecimal.ZERO; def _recvCount = 0; def _overdueAmt = BigDecimal.ZERO; def _overdueCount = 0
def _c15 = java.util.Calendar.getInstance(); _c15.setTime(_now2); _c15.add(java.util.Calendar.DAY_OF_MONTH,-15); def _ts15 = new java.sql.Timestamp(_c15.getTimeInMillis())
homePos.findAll { it.isCredit=='Y' }.each {
    def d=(homeBd(it.payableAmount)-homeBd(it.paidAmount)).max(BigDecimal.ZERO)
    if (d>0) { _recv+=d; _recvCount++; if (it.entryDate != null && it.entryDate.before(_ts15)) { _overdueAmt+=d; _overdueCount++ } }
}
homeCreditInvoices.each { def u=homeUnpaid(it); _recv+=u; _recvCount++; if (it.dueDate != null && it.dueDate.toLocalDateTime().toLocalDate().isBefore(_now2.toLocalDateTime().toLocalDate())) { _overdueAmt+=u; _overdueCount++ } }

// low stock (products at/below reorder point) + GST setup completeness
// low stock: only among INVENTORY-TRACKED products, and only surfaced when the tenant tracks a
// meaningful catalog (>=5). A LEFT-joined ProductStockView flags every untracked/stockless product as
// qoh<=0, so without this gate a non-inventory tenant floods with false "low stock" (e.g. 1135 for MARUTHI).
def _lowStock = 0; def _trkN = 0
try { if (_org2) {
    def _trkIds = ec.entity.find("mantle.product.Product").condition("ownerPartyId",_org2).condition("inventoryTracked","Y").selectField("productId").list()*.productId as Set
    _trkN = _trkIds.size()
    if (_trkN >= 5) ec.entity.find("zenith.erp.inventory.ProductStockView").condition("ownerPartyId",_org2).list().each { if (_trkIds.contains(it.productId)) { def q=_bd(it.totalQoh); def rp=_bd(it.reorderPoint); if (q<=0 || (rp>0 && q<=rp)) _lowStock++ } }
} } catch (Exception e) {}
def _prodTot2 = 0; def _gstSet = 0
try { if (_org2) { _prodTot2 = ec.entity.find("mantle.product.Product").condition("ownerPartyId",_org2).count()
    def _cf = ec.entity.conditionFactory
    def _gc = _cf.makeCondition([_cf.makeCondition("gstSlabId",_EC.IS_NOT_NULL,null),_cf.makeCondition("isGstExempt",_EC.EQUALS,"Y"),_cf.makeCondition("hsnCode",_EC.IS_NOT_NULL,null)],_EC.OR)
    _gstSet = ec.entity.find("mantle.product.Product").condition("ownerPartyId",_org2).condition(_gc).count() } } catch (Exception e) {}

// ===== A. AI Insights (severity-ranked) =====
aiInsights = []
def _ins = { sev, icon, title, detail, url, act -> aiInsights.add([sev:sev, icon:icon, title:title, detail:detail, url:url, act:act]) }
if (_overdueCount > 0) _ins('danger','⚠', _overdueCount+(_overdueCount==1?' account':' accounts')+' overdue', _fmt(_overdueAmt)+' at risk - follow up on ageing balances', '/apps/zenith/Contacts/ContactsDashboard', 'View')
else if (_recvCount > 0) _ins('ok','✓', 'Receivables under control', _fmt(_recv)+' outstanding across '+_recvCount+(_recvCount==1?' credit bill':' credit bills')+', none overdue', '/apps/zenith/Contacts/ContactsDashboard', 'View')
if (_salesCur > 0 || _salesPrior > 0) { def _g = (int)Math.round(_salesGrowth)
    if (_salesPrior <= 0) _ins('info','▲', _fmt(_salesCur)+' in sales this period', 'No prior-period sales to compare against — widen or shift the range for a trend', '/apps/zenith/sales/SalesDashboard', 'Report')
    else if (_salesGrowth >= 0) _ins('ok','▲', 'Sales trending up '+_g+'%', _fmt(_salesCur)+' this period vs '+_fmt(_salesPrior)+' prior', '/apps/zenith/sales/SalesDashboard', 'Report')
    else _ins((_salesGrowth < -20 ? 'warn':'info'),'▼', 'Sales down '+Math.abs(_g)+'%', _fmt(_salesCur)+' this period vs '+_fmt(_salesPrior)+' prior', '/apps/zenith/sales/SalesDashboard', 'Report') }
if (_lowStock > 0) _ins((_lowStock >= 10 ? 'danger':'warn'),'⚠', _lowStock+(_lowStock==1?' product':' products')+' low on stock', 'At or below reorder point - review purchasing', '/apps/zenith/Inventory/StockLevels', 'View')
if (_prodTot2 > 0) { def _pct = (int)Math.round(_gstSet*100.0/_prodTot2)
    if (_gstSet < _prodTot2) _ins((_pct < 80 ? 'warn':'info'),'⚠', (_prodTot2-_gstSet)+(((_prodTot2-_gstSet)==1)?' product':' products')+' missing GST setup', _gstSet+' of '+_prodTot2+' products GST-ready', '/apps/zenith/Inventory/FindProduct', 'Fix')
    else _ins('ok','✓', 'GST setup complete', 'All '+_prodTot2+' products have GST/HSN configured', '/apps/zenith/Inventory/FindProduct', 'View') }
def _sr = [danger:0, warn:1, info:2, ok:3]
aiInsights = aiInsights.sort { (_sr[it.sev] != null) ? _sr[it.sev] : 9 }
aiInsightsHas = !aiInsights.isEmpty()

// ===== B. Recent Transactions (latest sales invoices) =====
recentTx = []
try { if (_org2) {
    def _sdfR = new java.text.SimpleDateFormat("dd MMM, HH:mm")
    ec.entity.find("mantle.account.invoice.Invoice").condition("fromPartyId",_org2).condition("invoiceTypeEnumId","InvoiceSales")
        .condition("statusId",_EC.NOT_EQUAL,"InvoiceCancelled").condition("invoiceDate",_EC.GREATER_THAN_EQUAL_TO,dayStart ?: new java.sql.Timestamp(0L)).condition("invoiceDate",_EC.LESS_THAN,dayEndExcl ?: java.sql.Timestamp.valueOf('9999-12-31 00:00:00')).orderBy("-invoiceDate").orderBy("-lastUpdatedStamp").limit(4).list().each { inv ->
        def _pos = homePos.find { it.linkedInvoiceId == inv.invoiceId }
        def _u = _pos ? (homeBd(_pos.payableAmount)-homeBd(_pos.paidAmount)).max(BigDecimal.ZERO) : homeUnpaid(inv)
        def _ap = _pos ? homeBd(_pos.paidAmount) : homeBd(inv.appliedPaymentsTotal); def _dd = inv.dueDate
        def _st; def _cl
        if (inv.statusId == 'InvoiceInProcess') { _st='Draft'; _cl='dr' }
        else if (_dd != null && _dd.toLocalDateTime().toLocalDate().isBefore(_now2.toLocalDateTime().toLocalDate()) && _u > 0) { _st='Overdue'; _cl='od' }
        else if (_u > 0 && _ap > 0) { _st='Partial'; _cl='pt' }
        else if (_u > 0) { _st='Pending'; _cl='pd' }
        else if (inv.statusId == 'InvoicePmtRecvd' || (_ap > 0 && _u == 0)) { _st='Paid'; _cl='ok' }
        else { _st='Completed'; _cl='ok' }
        recentTx.add([no:(inv.customInvoiceNumber ?: (inv.gstInvoiceNumber ?: inv.invoiceId)),
            amt:_fmt(homeInvoiceTotal(inv)), st:_st, cl:_cl,
            date:(inv.invoiceDate != null ? _sdfR.format(inv.invoiceDate) : ''), url:('/apps/zenith/sales/EditInvoice?invoiceId='+java.net.URLEncoder.encode(inv.invoiceId,'UTF-8'))])
    }
} } catch (Exception e) { recentTx = []; homeDataErrors.add('Recent transactions'); ec.logger.warn('Home dashboard: recent transactions unavailable',e) }
recentTxHas = !recentTx.isEmpty()

// ===== C. Business Health (honest composite; average of AVAILABLE metrics) =====
bhMetrics = []; bhScore = 0; bhLabel = 'No data'; bhColor = '#9e9e9e'; bhHasData = false
try {
    def _pill = [good:['#DCFCE7','#059669'], warn:['#FEE2E2','#DC2626'], bad:['#FEE2E2','#991B1B'], na:['#EEF0F5','#64748B']]
    def _clr = { s -> s >= 80 ? 'good' : (s >= 55 ? 'warn' : 'bad') }
    def _addm = { nm, avail, sc, stt, ck -> def p = _pill[ck] ?: _pill.na; bhMetrics.add([name:nm, avail:avail, score:sc, status:stt, bg:p[0], fg:p[1], sev:ck]) }
    if (_salesCur <= 0 && _salesPrior <= 0) _addm('Sales', false, 0, 'No sales in range', 'na')
    else if (_salesPrior <= 0) _addm('Sales', true, 80, 'Active', 'good')
    else { def _s=_salesGrowth>=10?95:(_salesGrowth>=0?80:(_salesGrowth>=-15?60:35)); def _stt=_salesGrowth>=10?'Strong':(_salesGrowth>=0?'Good':(_salesGrowth>=-15?'Fair':'Weak')); def _gp=(int)Math.round(_salesGrowth)
        _addm('Sales', true, _s, _stt, _clr(_s)) }
    def _out = BigDecimal.ZERO; def _hasExp = false
    try { if (_org2) { def _el = ec.entity.find("zenith.erp.pos.PosExpense").condition("organizationPartyId",_org2).condition("expenseDate",_EC.GREATER_THAN_EQUAL_TO,_wStart).condition("expenseDate",_EC.LESS_THAN,_wEnd).list(); if (!_el.isEmpty()) { _hasExp = true; _el.each { _out += _bd(it.amount) } } } } catch (Exception e) {}
    if (_hasExp && _salesCur > 0) { double _r=(_out.doubleValue()*100.0/_salesCur.doubleValue()); def _s=_r<5?95:(_r<15?80:(_r<30?60:35)); def _stt=_r<5?'Strong':(_r<15?'Healthy':(_r<30?'Watch':'Tight')); _addm('Cash Flow', true, _s, _stt, _clr(_s)) }
    def _c90 = java.util.Calendar.getInstance(); _c90.setTime(_now2); _c90.add(java.util.Calendar.DAY_OF_MONTH,-90); def _ts90 = new java.sql.Timestamp(_c90.getTimeInMillis())
    def _ref90 = _salesIn(_ts90, _wEnd)
    if (_recv <= 0 && _ref90 <= 0) _addm('Receivables', false, 0, 'No activity yet', 'na')
    else if (_recv <= 0) _addm('Receivables', true, 100, 'Nothing outstanding', 'good')
    else { double _r=_ref90>0?(_recv.doubleValue()/_ref90.doubleValue()):1.0; def _s=_r<0.02?95:(_r<0.10?80:(_r<0.25?55:30)); def _stt=_r<0.02?'Healthy':(_r<0.10?'OK':(_r<0.25?'Needs Attention':'High')); _addm('Receivables', true, _s, _stt, _clr(_s)) }
    if (_prodTot2 > 0) {
        if (_trkN >= 5) { double _r=(_lowStock*1.0/_trkN); def _s=_r<0.05?95:(_r<0.15?80:(_r<0.30?55:30)); def _stt=_r<0.05?'Healthy':(_r<0.15?'Good':(_r<0.30?'Needs Attention':'Low stock')); _addm('Inventory', true, _s, _stt, _clr(_s)) }
        else { def _wp=ec.entity.find("mantle.product.Product").condition("ownerPartyId",_org2).condition("mrpAmount",_EC.GREATER_THAN,0G).count(); double _r=(_wp*1.0/_prodTot2); def _s=_r>=0.95?90:(_r>=0.80?75:(_r>=0.50?55:35)); def _stt=_r>=0.80?'Catalog ready':(_r>=0.50?'Some unpriced':'Many unpriced'); _addm('Inventory', true, _s, _stt, _clr(_s)) }
        double _r=(_gstSet*1.0/_prodTot2); def _s=_r>=0.95?95:(_r>=0.80?80:(_r>=0.50?55:30)); def _stt=_r>=0.95?'Compliant':(_r>=0.80?'Mostly set':(_r>=0.50?'Partial':'Needs setup')); _addm('GST', true, _s, _stt, _clr(_s))
    }
    def _av = bhMetrics.findAll { it.avail }; bhHasData = (_av.size() > 0)
    bhScore = bhHasData ? (int)Math.round(_av.sum { it.score } / _av.size()) : 0
    bhLabel = bhScore>=85?'Excellent':(bhScore>=70?'Good':(bhScore>=55?'Fair':'Needs Work'))
    bhColor = bhScore>=85?'#10B981':(bhScore>=70?'#059669':(bhScore>=55?'#D97706':'#DC2626'))
    bhBg = bhScore>=85?'#DCFCE7':(bhScore>=70?'#ECFCCB':(bhScore>=55?'#FEF3C7':'#FEE2E2'))
} catch (Exception e) { bhMetrics=[]; bhScore=0; bhLabel='No data'; bhColor='#9e9e9e'; bhHasData=false }

// ===== D. Top Selling Products (from the aggregated view-entity) =====
topSell = []
try { if (_org2) {
    def _pm = [:]
    ec.entity.find("zenith.erp.sales.InvoiceSalesProductByDateAgg").condition("fromPartyId",_org2).condition("invoiceTypeEnumId","InvoiceSales").condition("statusId","in",_finSale).condition("invoiceDate",_EC.GREATER_THAN_EQUAL_TO,dayStart ?: new java.sql.Timestamp(0L)).condition("invoiceDate",_EC.LESS_THAN,dayEndExcl ?: java.sql.Timestamp.valueOf('9999-12-31 00:00:00')).disableAuthz().list().each {
        def k = it.productId; if (k == null) return
        if (!_pm.containsKey(k)) _pm[k] = [qty:BigDecimal.ZERO, val:BigDecimal.ZERO]
        _pm[k].qty += _bd(it.totalQuantity); _pm[k].val += _bd(it.totalValue) }
    def _sorted = _pm.entrySet().sort { -(it.value.val.doubleValue()) }.take(5)
    def _max = _sorted ? _sorted[0].value.val : BigDecimal.ZERO
    _sorted.eachWithIndex { e, i ->
        def _p = ec.entity.find("mantle.product.Product").condition("productId", e.key).selectField("productName").disableAuthz().one()
        def _pct = (_max > 0) ? (int)Math.round(e.value.val.doubleValue()*100.0/_max.doubleValue()) : 0
        topSell.add([rank:(i+1), name:(_p?.productName ?: e.key.toString()), val:_fmt(e.value.val), units:zinr.inr(ec.l10n.format(e.value.qty,'#,##0')), pct:_pct]) }
} } catch (Exception e) { topSell = []; homeDataErrors.add('Top products'); ec.logger.warn('Home dashboard: top products unavailable',e) }
topSellHas = !topSell.isEmpty()

// ===== E. Pending Vendor Bills (unpaid purchase invoices, soonest due first) — mockup §10 =====
homePendingBills = []
homePendingInvoices.sort { a,b -> (a.dueDate?.time ?: Long.MAX_VALUE) <=> (b.dueDate?.time ?: Long.MAX_VALUE) }.take(5).each { inv ->
    def _dueDay=inv.dueDate ? inv.dueDate.toLocalDateTime().toLocalDate() : null
    def _todayDay=_now2.toLocalDateTime().toLocalDate()
    def _days=_dueDay ? java.time.temporal.ChronoUnit.DAYS.between(_todayDay,_dueDay) : null
    def _vendor=ec.entity.find('mantle.party.Organization').condition('partyId',inv.fromPartyId).disableAuthz().one()
    homePendingBills.add([no:inv.vendorInvoiceNumber ?: inv.invoiceId, vendor:_vendor?.organizationName ?: inv.fromPartyId ?: 'Vendor', amt:_fmt(homeUnpaid(inv)),
        due:(_days==null?'No due date':(_days<0?'Overdue by '+Math.abs(_days)+' days':(_days==0?'Due today':'Due in '+_days+' days'))),
        pri:(_days!=null && _days<=7?'High':(_days!=null && _days<=15?'Medium':'Low')), url:'/apps/zenith/Purchase/EditPurchaseInvoice?invoiceId='+java.net.URLEncoder.encode(inv.invoiceId,'UTF-8')])
}
homePendingHas = !homePendingBills.isEmpty()

// Landing redirect: the account's explicit "default dashboard" choice wins, else a role config.
// sendRedirect from screen actions is a no-op in this setup, so we hand a URL to a client-side
// redirect rendered first in the body. Unset / 'home' => stay here (unchanged for existing tenants).
landingRedirect = ''
try {
    def _ddMap = ['overview':'/apps/zenith/pos/OwnerDashboard', 'pos':'/apps/zenith/pos/Dashboard']
    // 1) the user's OWN choice wins (personal override)
    def _dd = ec.user.getPreference('DEFAULT_DASHBOARD')
    if (_dd && _ddMap[_dd]) landingRedirect = _ddMap[_dd]
    // 2) else the team/tenant default the owner set for all staff (org-level)
    if (!_dd && !landingRedirect) {
        def _org = ec.user.getPreference('ACTIVE_ORGANIZATION')
        if (_org && _org != '_NA_') {
            def _oc = ec.entity.find("zenith.erp.pos.OrgDashboardDefault").condition("organizationPartyId", _org).one()
            if (_oc?.dashboardKey && _ddMap[_oc.dashboardKey]) landingRedirect = _ddMap[_oc.dashboardKey]
        }
    }
    // 3) else any role-based dashboard config
    if (!_dd && !landingRedirect && myRoles) {
        def roleIds = myRoles*.roleTypeId
        def dashboardConfigs = ec.entity.find("zenith.erp.analytics.RoleDashboardConfig")
            .condition("roleTypeId", org.moqui.entity.EntityCondition.IN, roleIds)
            .condition("isActive", "Y").list()
        if (dashboardConfigs) { def sp = dashboardConfigs[0].dashboardScreenPath; if (sp) landingRedirect = "/apps/" + sp.replace('.', '/') }
    }
} catch (Exception e) { /* RoleDashboardConfig may not be seeded yet */ }

if (!activeOrgId) { bhHasData=false; aiInsights=[]; aiInsightsHas=false }
if (homeDataErrors.any { it in ['Sales','POS balances'] }) { bhHasData=false; aiInsights=[]; aiInsightsHas=false }
def _uri=ec.web.request.requestURI.replaceAll('/+$','').replaceFirst(/\.(qvt|vuet|html|json)$/, '')
if (!_uri.endsWith('/Dashboard')) _uri+='/Dashboard'
def _hour=java.util.Calendar.getInstance(); _hour.setTime(ec.user.nowTimestamp)
homeGreeting=_hour.get(java.util.Calendar.HOUR_OF_DAY)<12?'Good Morning':(_hour.get(java.util.Calendar.HOUR_OF_DAY)<17?'Good Afternoon':'Good Evening')
homeOrgName=activeOrgId ? ec.entity.find('mantle.party.Organization').condition('partyId',activeOrgId).disableAuthz().one()?.organizationName : null
homeNav=['Z_SALES','Z_PURCHASE','Z_ACCOUNTING','Z_INVENTORY','Z_HR','Z_SETTINGS'].collect { id -> filteredModules.find { it.id==id } }.findAll { it }.collect { [label:it.name,url:it.url] }
if (homeNav.any { it.label=='Accounting' }) homeNav.add(Math.max(0,homeNav.size()-1),[label:'Reports',url:'/apps/zenith/Accounting/ProfitAndLoss'])
homeRoute=_uri
homeDashConfig=groovy.json.JsonOutput.toJson([
    saveUrl:_uri+'/saveDashOrder', token:ec.web.sessionToken, order:dashOrderCsv, sizes:dashSizeCsv,
    nav:homeNav, redirect:landingRedirect, customize:showSettings=='1',
    weekly:[cats:new groovy.json.JsonSlurper().parseText(baWeekLabelsJson), series:new groovy.json.JsonSlurper().parseText(baWeekDataJson), total:baWeekTotal, sub:baWeekLabel],
    hourly:[cats:new groovy.json.JsonSlurper().parseText(baHourLabelsJson), series:new groovy.json.JsonSlurper().parseText(baHourDataJson), total:baHourTotal, sub:'Today']
])
